def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    choices = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([-1] + versions)

    order = names if name_order == "ascending" else list(reversed(names))
    best_key = None
    best = None

    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < bounds[0]
               or selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue

        rows = {}
        valid = True
        for name, version in selected.items():
            if version == -1:
                continue
            row = next(row for row in packages[name]
                       if row["version"] == version)
            rows[name] = row

        edges = {name: [] for name in rows}
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = selected[target]
                if version < dep["min"] or version > dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != set(rows):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in rows):
            continue

        key = tuple(selected[name] for name in order)
        if best_key is None or (key < best_key if preference == "minimum" else key > best_key):
            best_key = key
            best = {name: version for name, version in selected.items() if version != -1}

    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _dep_builder(preference, order):
    return lambda data: _dependency_solver(data, preference, order)


def _component_06(data):
    mode = data["rounding"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))

    def rounded(num, den):
        if mode == "half_up":
            return (num + den // 2) // den
        return num // den

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        idset = set(ids)
        if idset & blocked or not mandatory.issubset(idset):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    full = (1 << len(required)) - 1
    initial_mask = 0
    for i, node in enumerate(required):
        if node == data["source"]:
            initial_mask |= 1 << i
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    start_time = data["start"]
    distances = {start_state: start_time}
    queue = [(start_time, data["source"], initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask
                for i, required_node in enumerate(required):
                    if next_node == required_node:
                        next_mask |= 1 << i
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_remaining))
    return {"arrival": None}


